func Create(ctx *pulumi.Context, name pulumi.StringOutput) pulumi.Output {
    return name.ApplyT(func(value string) (string, error) {
        _, err := s3.NewBucket(ctx, "logs", &s3.BucketArgs{Bucket: pulumi.String(value)})
        return value, err
    })
}

